#!/usr/bin/env tsx
/** Copies the compiled ABI into src/ so the app never reads from artifacts/. */
import fs from "node:fs";
import path from "node:path";

const artifact = path.join(
  process.cwd(),
  "artifacts/contracts/LoopProofRegistry.sol/LoopProofRegistry.json",
);
if (!fs.existsSync(artifact)) {
  console.error("Run `npx hardhat compile` first.");
  process.exit(1);
}
const { abi } = JSON.parse(fs.readFileSync(artifact, "utf8")) as { abi: unknown[] };
const out = `// Generated by scripts/sync-abi.ts from contracts/LoopProofRegistry.sol.
// Do not edit by hand; run \`npx tsx scripts/sync-abi.ts\` after changing the contract.
export const loopProofRegistryAbi = ${JSON.stringify(abi, null, 2)} as const;
`;
fs.writeFileSync(path.join(process.cwd(), "src/lib/chain/abi.ts"), out);
console.log("wrote src/lib/chain/abi.ts");
